test("shared status helpers derive canonical task summaries", () => {
	assert.deepEqual(
		summarizeTasks([
			{ status: "completed" },
			{ status: "blocked" },
			{ status: "pending" },
		]),
		{
			total: 3,
			pending: 1,
			running: 0,
			blocked: 1,
			completed: 1,
			failed: 0,
			skipped: 0,
			interrupted: 0,
		},
	);
	assert.equal(
		deriveWorkflowStatus({
			total: 2,
			pending: 1,
			running: 0,
			blocked: 1,
			completed: 0,
			failed: 0,
			skipped: 0,
			interrupted: 0,
		}),
		"blocked",
	);
	// blocked outranks running so supervisors surface stuck runs instead of polling forever
	assert.equal(
		deriveWorkflowStatus({
			total: 2,
			pending: 0,
			running: 1,
			blocked: 1,
			completed: 0,
			failed: 0,
			skipped: 0,
			interrupted: 0,
		}),
		"blocked",
	);
	assert.equal(
		deriveWorkflowStatus({
			total: 2,
			pending: 0,
			running: 0,
			blocked: 0,
			completed: 1,
			failed: 0,
			skipped: 0,
			interrupted: 1,
		}),
		"interrupted",
	);
});

