test("spec-review partition helper joins verifier results and flags missing coverage", async (t) => {
	const cwd = makeProject();
	t.after(() =>
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 10,
			retryDelay: 100,
		}),
	);
	mkdirSync(join(cwd, "src"), { recursive: true });
	writeFileSync(join(cwd, "src/a.ts"), "a\n");
	const helper = (
		await import(
			pathToFileURL(
				join(
					process.cwd(),
					"workflows",
					"spec-review",
					"helpers",
					"spec-review-pipeline.mjs",
				),
			).href
		)
	).default;
	const result = await helper({
		sources: {
			"candidate-findings.main": {
				requirementCoverage: [
					{
						requirementId: "REQ-001",
						status: "partial",
						evidence: [
							{
								file: "src/example.ts",
								lineStart: 1,
								lineEnd: 1,
								quote: "missing",
							},
						],
					},
				],
				candidateFindings: [
					{
						id: "FINDING-001",
						title: "Kept issue",
						severity: "high",
						requirementIds: ["REQ-001"],
						claim: "Issue is real",
					},
					{
						id: "FINDING-002",
						title: "Dropped issue",
						severity: "medium",
						requirementIds: ["REQ-002"],
						claim: "Issue is not real",
					},
					{
						id: "FINDING-003",
						title: "Missing verifier",
						severity: "low",
						claim: "Needs verification",
					},
				],
				needsHuman: [{ question: "Spec ambiguity?" }],
				noIssueNotes: ["REQ-004 satisfied"],
			},
			"verify-findings.finding-001": {
				id: "FINDING-001",
				verdict: "KEEP",
				severity: "high",
				evidence: [
					{
						file: "src/a.ts",
						lineStart: 1,
						lineEnd: 1,
						quote: "a",
						relevance: "r",
					},
				],
				finalClaim: "Kept final claim",
				recommendedAction: "Fix it",
			},
			"verify-findings.finding-002": {
				id: "FINDING-002",
				verdict: "DROP",
				counterEvidence: [
					{ file: "src/a.ts", lineStart: 1, lineEnd: 1, quote: "a" },
				],
				finalClaim: "Not supported",
			},
			"verify-findings.orphan": {
				id: "FINDING-999",
				verdict: "KEEP",
			},
		},
		options: { mode: "partition" },
		context: {
			cwd,
			stateCwd: cwd ? stateDir(cwd) : undefined,
			specPath: "workflows/spec-review/spec.json",
			sourceStatuses: [
				{
					source: "candidate-findings",
					specId: "candidate-findings.main",
					stageId: "candidate-findings",
					taskId: "task-candidates",
					status: "completed",
				},
				{
					source: "verify-findings.finding-001",
					specId: "verify-findings.finding-001",
					stageId: "verify-findings",
					taskId: "task-verify-1",
					itemIdentity: "FINDING-001",
					placeholderSpecId: "verify-findings.item",
					status: "completed",
				},
				{
					source: "verify-findings.finding-002",
					specId: "verify-findings.finding-002",
					stageId: "verify-findings",
					taskId: "task-verify-2",
					itemIdentity: "FINDING-002",
					placeholderSpecId: "verify-findings.item",
					status: "completed",
				},
				{
					source: "verify-findings.orphan",
					specId: "verify-findings.finding-999",
					stageId: "verify-findings",
					taskId: "task-verify-orphan",
					itemIdentity: "FINDING-999",
					placeholderSpecId: "verify-findings.item",
					status: "completed",
				},
			],
		},
	});

	assert.equal(result.schema, "spec-review-partition-v1");
	assert.match(result.digest, /^sha256:[a-f0-9]{64}$/);
	assert.deepEqual(result.sourceStatusSummary, {
		metadataAvailable: true,
		total: 4,
		completed: 4,
		nonCompleted: 0,
		partialFailures: [],
	});
	assert.deepEqual(result.verifierCoverage.missingIds, ["FINDING-003"]);
	assert.deepEqual(result.verifierCoverage.orphanVerifierIds, ["FINDING-999"]);
	assert.deepEqual(
		result.finalFindings.map((finding) => finding.id),
		["FINDING-001"],
	);
	assert.deepEqual(
		result.droppedFindings.map((finding) => finding.id),
		["FINDING-002"],
	);
	assert(
		result.needsHuman.some((item) => item.source === "missing-verification"),
	);
	assert(result.needsHuman.some((item) => item.source === "orphan-verifier"));
	assert.deepEqual(result.noIssueNotes, ["REQ-004 satisfied"]);
});

test("bundled spec-review workflow compiles flat analysis and verification fanout", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "scout", "read, grep, find, ls");
		const specPath = join(
			process.cwd(),
			"workflows",
			"spec-review",
			"spec.json",
		);
		const spec = JSON.parse(readFileSync(specPath, "utf8"));
		parsePublicWorkflow(spec);
		assert.deepEqual(
			spec.artifactGraph.stages.slice(0, 4).map((stage) => stage.id),
			[
				"extract-spec",
				"map-implementation",
				"inspect-tests",
				"candidate-findings",
			],
		);
		const compiled = await compileWorkflow(spec, {
			cwd,
			specPath,
			task: "Compare docs/API_SPEC.md to src implementation and tests.",
		});
		assert.deepEqual(
			compiled.tasks.slice(0, 3).map((task) => task.key),
			["extract-spec.main", "map-implementation.main", "inspect-tests.main"],
		);
		assert.deepEqual(
			compiled.tasks.slice(0, 3).map((task) => task.dependsOn),
			[[], [], []],
		);
		const candidates = compiled.tasks.find(
			(task) => task.key === "candidate-findings.main",
		);
		assert.equal(candidates.kind, "reduce");
		assert.deepEqual(candidates.dependsOn, [
			"extract-spec.main",
			"map-implementation.main",
			"inspect-tests.main",
		]);
		const verifier = compiled.tasks.find(
			(task) => task.key === "verify-findings.item",
		);
		assert.equal(verifier.kind, "foreach");
		assert.deepEqual(verifier.dependsOn, ["candidate-findings.main"]);
		assert.deepEqual(verifier.foreach.from, {
			stage: "candidate-findings",
			path: "$.candidateFindings",
		});
		const partition = compiled.tasks.find(
			(task) => task.key === "partition-findings.main",
		);
		assert.equal(partition.kind, "support");
		assert.deepEqual(partition.dependsOn, [
			"candidate-findings.main",
			"verify-findings.item",
			"recheck-requirements.item",
		]);
		assert.deepEqual(partition.support, {
			uses: "./helpers/spec-review-pipeline.mjs",
			options: { mode: "partition" },
		});
		// 2026-11-04: unclear requirements are rechecked once (select-unclear -> foreach).
		const recheck = compiled.tasks.find(
			(task) => task.key === "recheck-requirements.item",
		);
		assert.equal(recheck.kind, "foreach");
		assert.deepEqual(recheck.dependsOn, ["select-unclear.main"]);
		assert.deepEqual(recheck.foreach.from, {
			stage: "select-unclear",
			path: "$.requirements",
		});
		assert.ok(
			partition.artifactGraph.output.controlSchemaPath.endsWith(
				join(
					"workflows",
					"spec-review",
					"schemas",
					"spec-review-partition-control.schema.json",
				),
			),
		);
		const reportStage = compiled.stages.find((stage) => stage.id === "report");
		assert.equal(reportStage.sourcePolicy, "require-success");
		const report = compiled.tasks.find((task) => task.key === "report.main");
		assert.equal(report.kind, "reduce");
		assert.equal(report.injectTask, true);
		assert.match(report.compiledPrompt, /# Task/);
		assert.deepEqual(report.dependsOn, ["partition-findings.main"]);
		const final = compiled.tasks.find((task) => task.key === "final.main");
		assert.equal(final.kind, "support");
		assert.deepEqual(final.dependsOn, [
			"report.main",
			"partition-findings.main",
		]);
		assert.deepEqual(final.artifactGraph.inputPolicy, {
			terminalBarrier: "all-sources",
			invalidateOnDependencyResume: true,
		});
		assert.equal(final.support.uses, "./helpers/render-spec-review-report.mjs");
		assert.ok(
			final.artifactGraph.output.controlSchemaPath.endsWith(
				join(
					"workflows",
					"spec-review",
					"schemas",
					"spec-review-render-control.schema.json",
				),
			),
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("bundled workflows compile warning-free and deep-review leaves reviewer fanout unconstrained", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "scout", "read, grep, find, ls");
		writeAgent(
			cwd,
			"researcher",
			// WP10 (C2, M12): the bundled researcher's web tools. Was the three workflow_web_* tools.
			"read, grep, find, ls, web_search, fetch_content",
		);
		for (const relativeSpecPath of bundledArtifactGraphSpecPaths()) {
			const bundledSpecPath = join(process.cwd(), relativeSpecPath);
			const bundledSpec = parsePublicWorkflow(
				JSON.parse(readFileSync(bundledSpecPath, "utf8")),
			);
			const bundledCompiled = await compileWorkflow(bundledSpec, {
				cwd,
				specPath: bundledSpecPath,
				task: "Audit the bundled workflow prompt contracts.",
			});
			assert.deepEqual(
				bundledCompiled.warnings,
				[],
				`${relativeSpecPath} emitted prompt/schema warnings`,
			);
			for (const stage of bundledSpec.artifactGraph.stages) {
				const prompt = stage.prompt ?? stage.each?.prompt;
				const schemaRef = stage.output?.controlSchema;
				if (!prompt || !schemaRef) continue;
				const schema = JSON.parse(
					readFileSync(join(dirname(bundledSpecPath), schemaRef), "utf8"),
				);
				for (const match of prompt.matchAll(/<control>(\{.*?\})<\/control>/g)) {
					const example = JSON.parse(match[1]);
					assert.deepEqual(
						validateJsonSchema(example, schema),
						{ valid: true, issues: [] },
						`${relativeSpecPath} stage ${stage.id} has an invalid control example`,
					);
				}
			}
		}
		const specPath = join(
			process.cwd(),
			"workflows",
			"deep-review",
			"spec.json",
		);
		const spec = JSON.parse(readFileSync(specPath, "utf8"));
		assert.deepEqual(
			spec.artifactGraph.stages.map((stage) => stage.id),
			[
				"triage",
				"reviewers",
				"dedup-findings",
				"devil-advocate",
				"partition-verdicts",
				"report-packet",
				"report",
				"final",
			],
		);
		const reviewersStage = spec.artifactGraph.stages.find(
			(stage) => stage.id === "reviewers",
		);
		assert.match(reviewersStage.each.prompt, /leading \+ or - marker/);
		const compiled = await compileWorkflow(spec, {
			cwd,
			specPath,
		});
		const reviewers = compiled.tasks.find(
			(task) => task.key === "reviewers.item",
		);
		const devilAdvocate = compiled.tasks.find(
			(task) => task.key === "devil-advocate.item",
		);
		const reportPacket = compiled.tasks.find(
			(task) => task.key === "report-packet.main",
		);
		const report = compiled.tasks.find((task) => task.key === "report.main");
		const final = compiled.tasks.find((task) => task.key === "final.main");
		assert.equal(reviewers?.stageMaxConcurrency, undefined);
		assert.match(
			reviewers?.compiledPrompt ?? "",
			/Validate the control object against the workflow-local control schema file: \.\/schemas\/deep-review-reviewers-control\.schema\.json/,
		);
		assert.match(
			reviewers?.compiledPrompt ?? "",
			/Never emit the file path or file name as the value of `control\.schema`\./,
		);
		assert.match(
			reviewers?.compiledPrompt ?? "",
			/If none is specified, use `stage-control-v1`; do not derive a value from the schema file name\./,
		);
		assert.doesNotMatch(
			reviewers?.compiledPrompt ?? "",
			/Use workflow-local control schema reference/,
		);
		assert.equal(devilAdvocate?.stageMaxConcurrency, undefined);
		assert.deepEqual(reportPacket?.dependsOn, ["partition-verdicts.main"]);
		assert.deepEqual(report?.dependsOn, ["report-packet.main"]);
		assert.deepEqual(final?.dependsOn, [
			"report.main",
			"partition-verdicts.main",
		]);
		assert.deepEqual(report?.runtime.tools, []);
		assert.deepEqual(report?.artifactGraph.requiredReads, [
			{
				source: "report-packet",
				artifact: "control",
				path: "$",
				maxChars: 15000,
				count: 1,
			},
		]);
		assert.deepEqual(report?.artifactGraph.requiredReadPolicy, [
			{
				source: "report-packet",
				artifact: "control",
				path: "$",
				maxChars: 15000,
				mustNotTruncate: true,
			},
		]);
		const triage = compiled.tasks.find((task) => task.key === "triage.main");
		for (const task of [triage, reviewers, devilAdvocate]) {
			assert.ok(task);
			assert.equal(task.artifactGraph.artifactAccess, "none");
			const prepared = await prepareDagTask(
				cwd,
				{
					runId: `deep_review_${task.key}`,
					tasks: [
						{
							taskId: "task-1",
							specId: task.key,
							cwd,
							files: {
								result: `.agent-workflow/workflows/deep_review_${task.key}/tasks/task-1/result.json`,
							},
						},
					],
				},
				{ tasks: [{ ...task, taskId: "task-1" }] },
				0,
			);
			assert.equal(
				prepared.runtime.toolProviders?.workflow_artifact,
				undefined,
			);
			assert.equal(prepared.runtime.tools.includes("workflow_artifact"), false);
			assert.doesNotMatch(prepared.compiledPrompt, /Workflow Artifact Inputs/);
		}

		const specReviewPath = join(
			process.cwd(),
			"workflows",
			"spec-review",
			"spec.json",
		);
		const specReviewCompiled = await compileWorkflow(
			parsePublicWorkflow(JSON.parse(readFileSync(specReviewPath, "utf8"))),
			{ cwd, specPath: specReviewPath, task: "Audit spec-review completion." },
		);
		const specReviewReport = specReviewCompiled.tasks.find(
			(task) => task.key === "report.main",
		);
		const specReviewFinal = specReviewCompiled.tasks.find(
			(task) => task.key === "final.main",
		);
		assert.equal(specReviewReport?.injectTask, true);
		assert.equal(specReviewFinal?.kind, "support");
		assert.deepEqual(specReviewFinal?.dependsOn, [
			"report.main",
			"partition-findings.main",
		]);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("bundled spec-review workflow materializes verifier and partitions verified findings", async () => {
	const cwd = makeProject();
	try {
		mkdirSync(join(cwd, "src"), { recursive: true });
		writeFileSync(join(cwd, "src/example.ts"), "missing\n");
		writeFileSync(
			join(cwd, "SPEC.md"),
			"The implementation must match the required behavior.\n",
		);
		writeAgent(cwd, "scout", "read, grep, find, ls");
		captureWorkerPrompts([]);
		const specPath = join(
			process.cwd(),
			"workflows",
			"spec-review",
			"spec.json",
		);
		const spec = JSON.parse(readFileSync(specPath, "utf8"));
		const compiled = await compileWorkflow(spec, {
			cwd,
			specPath,
			task: "Compare docs/API_SPEC.md to src implementation and tests.",
		});
		const { run } = await createWorkflowRunRecord(cwd, compiled, specPath);
		await writeStaticRunArtifacts(cwd, run, compiled, spec);
		await writeRunRecord(cwd, run);

		await completeTask(cwd, taskBySpec(run, "extract-spec.main"), {
			specSources: ["SPEC.md"],
			requirements: [
				{
					id: "REQ-001",
					requirement: "The implementation must match the required behavior.",
					specEvidence: {
						file: "SPEC.md",
						lineStart: 1,
						lineEnd: 1,
						quote: "The implementation must match the required behavior.",
					},
					priority: "medium",
					implementationSignals: [],
					testSignals: [],
				},
			],
		});
		await completeTask(cwd, taskBySpec(run, "map-implementation.main"), {
			implementationMap: [],
		});
		await completeTask(cwd, taskBySpec(run, "inspect-tests.main"), {
			testMap: [],
		});
		await completeTask(cwd, taskBySpec(run, "candidate-findings.main"), {
			requirementCoverage: [{ requirementId: "REQ-001", status: "partial" }],
			candidateFindings: [
				{
					id: "FINDING-001",
					requirementIds: ["REQ-001"],
					severity: "medium",
					title: "Missing behavior",
					claim: "Implementation misses behavior",
					specEvidence: [
						"The implementation must match the required behavior.",
					],
					implementationEvidence: [],
					testEvidence: [],
					uncertainty: "Verify implementation behavior.",
				},
			],
			needsHuman: [],
			noIssueNotes: [],
		});
		await writeRunRecord(cwd, run);

		await scheduleRun(cwd, run.runId);
		let current = await readRunRecord(cwd, run.runId);
		assert.deepEqual(
			current.tasks.map((task) => task.specId),
			[
				"extract-spec.main",
				"map-implementation.main",
				"inspect-tests.main",
				"candidate-findings.main",
				"verify-findings.item",
				"verify-findings.finding-001",
				"select-unclear.main",
				"recheck-requirements.item",
				"partition-findings.main",
				"report.main",
				"final.main",
			],
		);
		// No requirement was left unclear: the recheck foreach has no items.
		assert.deepEqual(taskBySpec(current, "partition-findings.main").dependsOn, [
			"candidate-findings.main",
			"verify-findings.finding-001",
			"recheck-requirements.item",
		]);
		const candidateTask = taskBySpec(current, "candidate-findings.main");
		const upstreamManifestSources = [
			"extract-spec",
			"map-implementation",
			"inspect-tests",
		].map((stageId) => {
			const sourceTask = taskBySpec(current, `${stageId}.main`);
			const sourceDir = dirname(join(stateDir(cwd), sourceTask.files.result));
			return {
				source: stageId,
				taskId: sourceTask.taskId,
				specId: sourceTask.specId,
				stageId: sourceTask.stageId,
				status: sourceTask.status,
				artifacts: { control: { path: join(sourceDir, "control.json") } },
			};
		});
		writeFileSync(
			join(
				dirname(join(stateDir(cwd), candidateTask.files.result)),
				"source-manifest.json",
			),
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId: current.runId,
				taskId: candidateTask.taskId,
				sources: upstreamManifestSources,
			}),
		);

		await completeTask(
			cwd,
			taskBySpec(current, "verify-findings.finding-001"),
			{
				id: "FINDING-001",
				verdict: "KEEP",
				severity: "medium",
				evidence: [
					{
						file: "src/example.ts",
						lineStart: 1,
						lineEnd: 1,
						quote: "missing",
						relevance: "gap",
					},
				],
				counterEvidence: [],
				finalClaim: "Implementation misses behavior",
				recommendedAction: "Implement the missing behavior",
			},
		);
		await writeRunRecord(cwd, current);

		await scheduleRun(cwd, current.runId);
		current = await readRunRecord(cwd, current.runId);
		const partitionTask = taskBySpec(current, "partition-findings.main");
		assert.equal(partitionTask.status, "completed");
		const partitionResult = JSON.parse(
			readFileSync(
				join(
					dirname(join(stateDir(cwd), partitionTask.files.result)),
					"control.json",
				),
				"utf8",
			),
		);
		assert.deepEqual(partitionResult.verifierCoverage.missingIds, []);
		assert.deepEqual(
			partitionResult.finalFindings.map((finding) => finding.id),
			["FINDING-001"],
		);
		writeFileSync(
			join(
				dirname(join(stateDir(cwd), partitionTask.files.result)),
				"source-manifest.json",
			),
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId: current.runId,
				taskId: partitionTask.taskId,
				sources: [
					{
						source: "candidate-findings",
						taskId: taskBySpec(current, "candidate-findings.main").taskId,
						specId: "candidate-findings.main",
						stageId: "candidate-findings",
						status: "completed",
						artifacts: {
							control: {
								path: join(
									dirname(join(stateDir(cwd), candidateTask.files.result)),
									"control.json",
								),
							},
						},
					},
				],
			}),
		);
		assert.deepEqual(partitionResult.verdictCounts, {
			keep: 1,
			weaken: 0,
			drop: 0,
			needsHuman: 0,
			missingVerification: 0,
			invalidVerifier: 0,
			orphanVerifier: 0,
		});
	} finally {
		setTaskRuntimeApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow helper loader resolves directory-local helpers", async () => {
	const cwd = makeProject();
	try {
		const workflowDir = join(cwd, "workflows", "bundle");
		mkdirSync(join(workflowDir, "helpers"), { recursive: true });
		const specPath = join(workflowDir, "spec.json");
		const helperPath = join(workflowDir, "helpers", "audit.mjs");
		writeFileSync(specPath, JSON.stringify(workflowSpec("unit-scout")));
		writeFileSync(
			helperPath,
			"export default async function helper(input) { return { ok: true, sources: input.sources }; }\n",
		);

		const resolved = await resolveWorkflowHelperRef(
			"./helpers/audit.mjs",
			specPath,
		);
		assert.equal(
			resolved.path.endsWith("/workflows/bundle/helpers/audit.mjs"),
			true,
		);

		const helper = await loadWorkflowHelper("./helpers/audit.mjs", specPath);
		assert.deepEqual(
			await helper({
				sources: { verify: { ok: true } },
				context: { specPath, cwd, stateCwd: cwd ? stateDir(cwd) : undefined },
			}),
			{
				ok: true,
				sources: { verify: { ok: true } },
			},
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow helper loader rejects external or invalid helper refs", async () => {
	const cwd = makeProject();
	try {
		const workflowDir = join(cwd, "workflows", "bundle");
		mkdirSync(join(workflowDir, "helpers"), { recursive: true });
		const specPath = join(workflowDir, "spec.json");
		writeFileSync(specPath, JSON.stringify(workflowSpec("unit-scout")));
		writeFileSync(
			join(workflowDir, "helpers", "not-function.mjs"),
			"export default 1;\n",
		);

		await assert.rejects(
			() => resolveWorkflowHelperRef("../outside.mjs", specPath),
			/parent-directory/,
		);
		await assert.rejects(
			() => resolveWorkflowHelperRef("/tmp/outside.mjs", specPath),
			/directory-local/,
		);
		await assert.rejects(
			() => resolveWorkflowHelperRef("file://helpers/audit.mjs", specPath),
			/directory-local/,
		);
		await assert.rejects(
			() => resolveWorkflowHelperRef("npm:pkg", specPath),
			/directory-local/,
		);
		await assert.rejects(
			() => resolveWorkflowHelperRef("~/.pi/helper.mjs", specPath),
			/directory-local/,
		);
		await assert.rejects(
			() => resolveWorkflowHelperRef("./helpers/audit.js", specPath),
			/relative \.mjs file/,
		);
		await assert.rejects(
			() => loadWorkflowHelper("./helpers/not-function.mjs", specPath),
			/default-export a function/,
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

