test("minimal JSON schema validator enforces control schema subset", () => {
	const schema = {
		type: "object",
		required: ["schema", "digest", "items"],
		properties: {
			schema: { type: "string" },
			digest: { type: "string", minLength: 1 },
			items: {
				type: "array",
				minItems: 1,
				items: {
					type: "object",
					required: ["id"],
					properties: { id: { type: "string" } },
				},
			},
		},
	};
	assert.equal(
		validateJsonSchema(
			{ schema: "stage-control-v1", digest: "ok", items: [{ id: "a" }] },
			schema,
		).valid,
		true,
	);
	const invalid = validateJsonSchema(
		{ schema: "stage-control-v1", digest: "ok", items: [] },
		schema,
	);
	assert.equal(invalid.valid, false);
	assert.ok(invalid.issues.some((issue) => issue.path === "$.items"));
});

test("workflow-guide scaffolds load and compile without warnings", async () => {
	const scaffoldsRoot = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"skills",
		"workflow-guide",
		"scaffolds",
	);
	const names = readdirSync(scaffoldsRoot, { withFileTypes: true })
		.filter((entry) => entry.isDirectory())
		.map((entry) => entry.name)
		.sort();
	assert.ok(names.length >= 6, "expected at least six scaffold bundles");
	for (const name of names) {
		const specPath = join(scaffoldsRoot, name, "spec.json");
		const loaded = await loadWorkflowSpec(specPath, scaffoldsRoot);
		const compiled = await compileWorkflow(loaded.spec, {
			cwd: scaffoldsRoot,
			specPath: loaded.specPath,
			task: "scaffold regression task",
		});
		assert.deepEqual(
			compiled.warnings ?? [],
			[],
			`scaffold ${name} must compile without validation warnings`,
		);
	}
});

